'use server';

import { auth } from './index.js';
import {
  createFirstUser,
  createUser,
  getAllUsers,
  deleteUser,
  getUserByEmail,
  updateUserEmail,
  updateUserRole,
  updateUserPasswordById,
  verifyPassword,
} from '../db/users.js';

async function requireAuth() {
  const session = await auth();
  if (!session?.user?.id) throw new Error('Unauthorized');
  return session.user;
}

async function requireAdmin() {
  const user = await requireAuth();
  if (user.role !== 'admin') throw new Error('Forbidden');
  return user;
}

/**
 * Create the first admin user (setup action).
 * Uses atomic createFirstUser() to prevent race conditions.
 * No session/token is created — the admin must log in through the normal auth flow.
 *
 * @param {string} email
 * @param {string} password
 * @returns {Promise<{ success?: boolean, error?: string }>}
 */
export async function setupAdmin(email, password) {
  if (!email || !password) {
    return { error: 'Email and password are required.' };
  }
  if (password.length < 8) {
    return { error: 'Password must be at least 8 characters.' };
  }

  const created = createFirstUser(email, password);
  if (!created) {
    return { error: 'Setup already completed.' };
  }

  return { success: true };
}

/**
 * Get all users.
 */
export async function getUsers() {
  await requireAdmin();
  return getAllUsers();
}

